function navIcons() {
  const strip = t => t.replace(/^[\s\p{Extended_Pictographic}\uFE0F\u200D]+/u, '');
  document.querySelectorAll('.admin-nav-item[data-tab], .admin-mobile-nav li[data-tab]').forEach(li => { if (li.querySelector('.nav-ico')) return; const d = NAV_ICONS[li.dataset.tab]; li.textContent = strip(li.textContent); if (d) li.insertAdjacentHTML('afterbegin', `<svg class="nav-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`); });
  document.querySelectorAll('.store-mobile-nav .mobile-nav-list li').forEach(li => { li.childNodes.forEach(n => { if (n.nodeType === 3) n.textContent = strip(n.textContent); }); });
}
